import operator
import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    functions = {"SUM", "MIN", "MAX", "IF"}
    comparisons = {
        "=": operator.eq,
        "<>": operator.ne,
        "<": operator.lt,
        "<=": operator.le,
        ">": operator.gt,
        ">=": operator.ge,
    }
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    token_pattern = re.compile(
        r"[0-9]+|[A-Z]+[0-9]*|<=|>=|<>|[+\-*/():,=<>]"
    )

    def integer(text):
        try:
            return int(text)
        except ValueError:
            # Handle literals exceeding Python's decimal conversion limit.
            text = text.strip()
            sign = -1 if text[0] == "-" else 1
            if text[0] in "+-":
                text = text[1:]
            value = 0
            for offset in range(0, len(text), 9):
                part = text[offset:offset + 9]
                value = value * 10 ** len(part) + int(part)
            return sign * value

    def parse(source):
        values = []
        operators = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append((op, left, right))

        for match in token_pattern.finditer(source):
            token = match.group()

            if token[0].isdigit():
                values.append(integer(token))
                expect_operand = False

            elif token in functions:
                operators.append(token)

            elif token[0].isalpha():
                values.append(token)
                expect_operand = False

            elif token == "(":
                operators.append(("(", len(values)))
                expect_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expect_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                start = operators.pop()[1]

                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(values[start:])
                    del values[start:]
                    values.append((function, arguments))

                expect_operand = False

            else:
                if token == "-" and expect_operand:
                    operators.append("neg")
                else:
                    while (
                        operators
                        and operators[-1] in precedence
                        and precedence[operators[-1]] >= precedence[token]
                    ):
                        reduce_operator()
                    operators.append(token)

                expect_operand = True

        while operators:
            reduce_operator()

        return values[0]

    expressions = {
        name: parse(content[1:]) if content.startswith("=") else integer(content)
        for name, content in cells.items()
    }

    def expand_arguments(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first, last = argument[1], argument[2]
                left, right = sorted((ord(first[0]), ord(last[0])))
                top, bottom = sorted((int(first[1:]), int(last[1:])))

                for row in range(top, bottom + 1):
                    for column in range(left, right + 1):
                        name = chr(column) + str(row)
                        if name in cells:
                            yield name
            else:
                yield argument

    cache = {}
    active = set()

    for root in cells:
        if root in cache:
            continue

        tasks = [("eval", root)]
        values = []

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "eval":
                node = task[1]

                if isinstance(node, int):
                    values.append(node)

                elif isinstance(node, str):
                    if node in cache:
                        values.append(cache[node])
                    elif node not in expressions:
                        values.append(0)
                    elif node in active:
                        values.append("#CYCLE!")
                    else:
                        active.add(node)
                        tasks.append(("save", node))
                        tasks.append(("eval", expressions[node]))

                else:
                    op = node[0]

                    if op == "neg":
                        tasks.append(("negate",))
                        tasks.append(("eval", node[1]))

                    elif op == "IF":
                        condition, then_branch, else_branch = node[1]
                        tasks.append(("choose", then_branch, else_branch))
                        tasks.append(("eval", condition))

                    elif op in functions:
                        tasks.append((
                            "aggregate", op, expand_arguments(node[1]), None
                        ))

                    else:
                        tasks.append(("left_done", op, node[2]))
                        tasks.append(("eval", node[1]))

            elif action == "save":
                name = task[1]
                cache[name] = values[-1]
                active.remove(name)

            elif action == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif action == "left_done":
                left = values.pop()

                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("eval", task[2]))

            elif action == "right_done":
                right = values.pop()

                if isinstance(right, str):
                    values.append(right)
                    continue

                op, left = task[1], task[2]

                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        result = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            result = -result
                else:
                    result = int(comparisons[op](left, right))

                values.append(result)

            elif action == "choose":
                condition = values.pop()

                if isinstance(condition, str):
                    values.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("eval", branch))

            elif action == "aggregate":
                function, arguments, accumulator = task[1:]
                argument = next(arguments, None)

                if argument is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append((
                        "argument_done", function, arguments, accumulator
                    ))
                    tasks.append(("eval", argument))

            elif action == "argument_done":
                value = values.pop()

                if isinstance(value, str):
                    values.append(value)
                    continue

                function, arguments, accumulator = task[1:]

                if accumulator is None:
                    accumulator = value
                elif function == "SUM":
                    accumulator += value
                elif function == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append((
                    "aggregate", function, arguments, accumulator
                ))

    return {name: cache[name] for name in cells}
